#include <cstdio>

#define debug(s, t) printf("x" # s "= %d, x" # t "= %s", \
x ## s, x ## t)
#define INCFILE(n) vers ## n
#define glue(a, b) a ## b
#define xglue(a, b) glue(a, b)
#define HIGHLOW "hello"
#define LOW LOW ", world"

int main() {
    int vers1 = 42;
    const char* vers2 = "example";
    int x1 = 10, x2 = 20;
    debug(1, 2);
    // Using token pasting to generate variable names
    int version1 = 100;
    int version2 = 200;
    printf("Version 1: %d\n", version1);
    printf("Version 2: %d\n", version2);
    // Using glue to concatenate tokens
    int xgluevar = 123;
    printf("xgluevar: %d\n", xgluevar);
    // Using macro to concatenate string macros
    printf("Combined string: %s%s\n", HIGHLOW, LOW);
    return 0;
}
